def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    if s == t:
        return 0
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        if w == 0:
            continue
        adj[u].append((v, w))
    visited = [False] * n
    paths = []
    dfs(s, t, adj, visited, [], paths)
    if len(paths) == 0:
        return -1
    lengths = [sum(weights) for _, weights in paths]
    return min(lengths)

def dfs(u: int, t: int, adj: list[list[tuple[int, int]]], visited: list[bool], current_path: list[int], paths: list[list[int]]):
    visited[u] = True
    current_path.append(u)
    if u == t:
        paths.append((u, current_path.copy()))
    else:
        for v, _ in adj[u]:
            if visited[v] == False:
                dfs(v, t, adj, visited, current_path, paths)
        for v, weight in adj[u]:
            if visited[v] == True and weight == 1:
                current_path.append(v)
                paths.append((u, current_path.copy()))
                current_path.pop()
    visited[u] = False
    current_path.pop()

def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    import heapq
    INF = float('inf')
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    dist = [INF] * n
    queue = [(0, s)]
    dist[s] = 0
    while queue:
        current_dist, current_node = heapq.heappop(queue)
        if current_dist > dist[current_node]:
            continue
        for next_node, next_dist in graph[current_node]:
            new_dist = current_dist + next_dist
            if new_dist < dist[next_node]:
                dist[next_node] = new_dist
                heapq.heappush(queue, (new_dist, next_node))
    if s == t:
        return 0
    elif dist[t] == INF:
        return -1
    else:
        return dist[t]

def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    from collections import deque
    adj_list = [[] for _ in range(n)]
    for u, v, w in edges:
        adj_list[u].append((v, w))
    distances = [float('inf')] * n
    if s == t:
        return 0
    queue = deque()
    queue.append(s)
    distances[s] = 0
    while queue:
        u = queue.popleft()
        for v, weight in adj_list[u]:
            if distances[v] > distances[u] + weight:
                distances[v] = distances[u] + weight
                queue.append(v)
    return distances[t] if distances[t] != float('inf') else -1

